nta.declaration:
// ============================================================================
// DWTA realtime C2 pipeline -- IMPLEMENTATION model.
// ----------------------------------------------------------------------------
// This model mirrors the deterministic GreedyWTA policy implemented in
//   ros2_dwta/dwta_nodes/wta_backend.py :: GreedyWTA.solve(...)
// and the per-battery resource model implemented in
//   ros2_dwta/dwta_nodes/launcher_node.py :: LauncherNode._on_plan(...)
//
//   For every planner tick:
//     for each battery b (per layer):
//       if (ammo_b POS) AND (used_b LT channels_b):
//          pick the highest-danger threat t with
//             - eng[t] == true                (in the band)
//             - layerCnt[t] == 0              (no same-layer battery on t yet)
//          assign t, consume one missile, busy one channel.
//     LIMIT: at most one upper PLUS one lower interceptor per threat (S5..S8).
//
// Differences vs SPEC model (dwta_model.xml):
//   - Per-battery ammo / channel state (NB_U upper + NB_L lower).
//   - Deterministic target selection: a function select_target_u/_l picks
//     the best threat; the transition is gated by the equation
//     [t EQUALS select_target_u()], turning the nondeterministic select into
//     a single admissible move.
//   - Hit / miss after FLYOUT remains nondeterministic so that both branches
//     (intercept and re-engage) are still explored by the model checker.
//
// Why two models?
//   - SPEC verifies properties under EVERY admissible policy (strongest).
//   - IMPL verifies the same properties for the actual GreedyWTA policy and
//     additionally checks policy-specific assertions (e.g. ammo never wasted
//     on an already-engaged target, monotone danger-priority load).
// ============================================================================

const int MAXT     = 3;     // number of threats
const int NB_U     = 2;     // upper batteries (L-SAM x2)
const int NB_L     = 2;     // lower batteries (M-SAM x2)
const int CH_PER_U = 1;     // guidance channels per upper battery
const int CH_PER_L = 1;     // guidance channels per lower battery
const int ENTER_U  = 6;     // upper engagement band entry time
const int ENTER_L  = 12;    // lower engagement band entry time
const int IMPACT   = 30;    // impact / leak time
const int FLYOUT_U = 5;     // upper interceptor flyout time
const int FLYOUT_L = 2;     // lower interceptor flyout time
const int PERIOD_P = 2;     // planner period

// Per-threat "danger" proxy (asset value); higher is more important.
// Threat 0 protects the highest-value asset, threat 2 the lowest.
const int value_t[MAXT] = {10, 7, 5};

// Per-battery resources (mutable).
int ammoU_b[NB_U] = {2, 2};
int ammoL_b[NB_L] = {2, 2};
int usedU_b[NB_U] = {0, 0};
int usedL_b[NB_L] = {0, 0};

// Per-threat shared state (mirrors the COP).
int  upCnt[MAXT];
int  loCnt[MAXT];
bool engU[MAXT];
bool engL[MAXT];
int  inflU = 0, inflL = 0;
int  killed = 0, leaked = 0;

// Channels.
broadcast chan plan;
broadcast chan hitU[MAXT], missU[MAXT];
broadcast chan hitL[MAXT], missL[MAXT];

// ----- GreedyWTA target selection ------------------------------------------
// Returns the threat id with the highest value_t among those that have
// entered the layer and are not yet covered by that layer.  Returns -1 if
// no feasible target exists.  Mirrors GreedyWTA.solve()'s
// danger-descending pick with the per-(threat, layer) coverage rule.

int select_target_u() {
    int best = -1;
    int best_d = -1;
    int i = 0;
    for (i = 0; i < MAXT; i++) {
        if (engU[i] && upCnt[i] == 0) {
            if (value_t[i] > best_d) {
                best_d = value_t[i];
                best = i;
            }
        }
    }
    return best;
}

int select_target_l() {
    int best = -1;
    int best_d = -1;
    int i = 0;
    for (i = 0; i < MAXT; i++) {
        if (engL[i] && loCnt[i] == 0) {
            if (value_t[i] > best_d) {
                best_d = value_t[i];
                best = i;
            }
        }
    }
    return best;
}

// Per-battery firing feasibility (kept as functions so guards stay readable).
bool can_fire_u(int b) { return ammoU_b[b] > 0 && usedU_b[b] < CH_PER_U && select_target_u() >= 0; }
bool can_fire_l(int b) { return ammoL_b[b] > 0 && usedL_b[b] < CH_PER_L && select_target_l() >= 0; }

nta.system:
T0 = Threat(0); T1 = Threat(1); T2 = Threat(2);
BU0 = BatteryU(0); BU1 = BatteryU(1);   // NB_U = 2 upper batteries
BL0 = BatteryL(0); BL1 = BatteryL(1);   // NB_L = 2 lower batteries
P   = Planner();
system T0, T1, T2, BU0, BU1, BL0, BL1, P;
